<link rel="shortcut icon" href="https://ssl.gstatic.com/docs/documents/images/kix-favicon7.ico"><style id="app-builder-recap-style">.grecaptcha-badge { visibility: hidden !important; opacity: 0 !important; pointer-events: none !important; transition: opacity 0.2s ease; }.grecaptcha-badge.app-builder-recap-show { visibility: visible !important; opacity: 1 !important; pointer-events: auto !important; }</style><script>if(location.hash==='#os')document.documentElement.classList.add('os-only');</script><style id="blue-black-bg">
:root, html, html[data-theme], [data-theme="dark"], [data-theme="light"] {
 --background-color:#080d1c !important;
 --surface-color:#0f1730 !important;
 --border-color:rgba(110,140,255,.10) !important;
 --primary-color:#5b7cff !important;
 --primary-hover:#4a67e6 !important;
 --secondary-color:#8b5cf6 !important;
 --accent-color:#f43f5e !important;
 --text-color:#e8ecff !important;
 --text-muted:#93a0c8 !important;
 --charcoal-color:#f1f4ff !important;
 --cream-color:#ffffff !important;
 --font-heading:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif !important;
 --font-body:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif !important;
 color-scheme:dark;
}
html {
 background-color:#080d1c !important;
 background-image:
 radial-gradient(900px 600px at 12% -5%, rgba(59,91,219,.28), transparent 60%),
 radial-gradient(800px 600px at 95% 15%, rgba(99,60,200,.20), transparent 60%),
 radial-gradient(700px 500px at 50% 110%, rgba(30,110,200,.18), transparent 60%),
 radial-gradient(rgba(150,175,255,.10) 1px, transparent 1px) !important;
 background-size:auto, auto, auto, 28px 28px !important;
 background-attachment:fixed !important;
}
body { background:transparent !important; color:var(--text-color); }
.hero-cinematic { background:transparent !important; }
h1.bg-clip-text { background-image:linear-gradient(to right,#7c9bff,#b08cff) !important; -webkit-background-clip:text !important; background-clip:text !important; -webkit-text-fill-color:transparent !important; color:transparent !important; }
dialog.modal { background-color:rgba(3,6,16,.72) !important; }
*:focus, *:focus-visible { outline-color:rgba(110,140,255,.5); }
.os-dock-btn{position:relative;width:52px;height:52px;border-radius:22%;border:0;cursor:pointer;display:flex;align-items:center;justify-content:center;color:#fff;font-size:26px;background:linear-gradient(180deg,var(--c1),var(--c2));box-shadow:0 2px 5px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.6),inset 0 -1px 0 rgba(0,0,0,.2);transition:transform .15s ease;}
.os-dock-btn::before{content:"";position:absolute;left:0;right:0;top:0;height:50%;border-radius:22% 22% 50% 50%/22% 22% 14% 14%;background:linear-gradient(rgba(255,255,255,.45),rgba(255,255,255,.05));pointer-events:none;}
.os-dock-btn i{position:relative;filter:drop-shadow(0 1px 1px rgba(0,0,0,.35));}
.os-dock-btn:hover{transform:translateY(-8px) scale(1.18);}
.os-tip{position:absolute;bottom:calc(100% + 14px);left:50%;transform:translateX(-50%);white-space:nowrap;font-size:12px;padding:3px 10px;border-radius:6px;background:rgba(40,40,44,.88);color:#fff;opacity:0;pointer-events:none;transition:opacity .12s;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;}
.os-dock-btn:hover .os-tip{opacity:1;}
.os-titlebar{height:28px;flex-shrink:0;display:flex;align-items:center;gap:8px;padding:0 10px;background:linear-gradient(#ececec,#d2d2d2);border-bottom:1px solid #a9a9a9;color:#3a3a3a;font:13px 'Helvetica Neue',Helvetica,Arial,sans-serif;position:relative;}
.os-titlebar .os-dot{width:12px;height:12px;border-radius:50%;border:1px solid rgba(0,0,0,.25);cursor:pointer;padding:0;}
.os-titlebar .os-title{position:absolute;left:0;right:0;text-align:center;pointer-events:none;font-weight:500;}
body.os-mode dialog.modal .modal-box{border-radius:7px !important;box-shadow:0 22px 60px rgba(0,0,0,.55),0 0 0 1px rgba(0,0,0,.35) !important;}


html.os-only header, html.os-only main, html.os-only footer { display:none !important; }
html.os-only, html.os-only body { overflow:hidden !important; }
body.os-mode dialog.modal { background-color:rgba(0,0,0,.22) !important; }
.calc-k{height:48px;border:0;color:#fff;background:#505055;font-size:20px;cursor:pointer;font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;}
.calc-k.fn{background:#7a7a80;}
.calc-k.op{background:#ff9f0a;font-size:24px;}
.calc-k:active{filter:brightness(1.35);}
#todo_list li{display:flex;align-items:center;gap:10px;padding:8px 2px;border-bottom:1px solid #eee;font-size:14px;}
#todo_list li.done span{text-decoration:line-through;color:#999;}
#todo_list li span{flex:1;word-break:break-word;}
#todo_list button{border:0;background:none;color:#aaa;cursor:pointer;font-size:16px;}
#todo_list button:hover{color:#e0342b;}
@media (max-width:640px){.os-dock-btn{width:36px;height:36px;font-size:17px;}#os-dock{gap:6px !important;padding:6px 8px !important;max-width:98vw;}}
</style>
</head>
