0%20600%20L420%20650%20L620%20610%20L900%20680%20L1200%20620%20L1400%20670%20L1600%20630%20L1600%20900%20L0%20900Z%27%20fill%3D%27%234d6a4c%27%20opacity%3D%27.9%27/%3E%0A%3Cpath%20d%3D%27M0%20760%20L60%20700%20L90%20760%20L150%20690%20L190%20765%20L260%20705%20L300%20770%20L380%20700%20L430%20775%20L520%20710%20L560%20780%20L650%20715%20L700%20785%20L800%20720%20L850%20790%20L950%20725%20L1000%20790%20L1100%20715%20L1150%20785%20L1250%20705%20L1300%20780%20L1390%20700%20L1440%20775%20L1520%20710%20L1560%20770%20L1600%20720%20L1600%20900%20L0%20900Z%27%20fill%3D%27url%28%23g%29%27/%3E%0A%3C/svg%3E") center/cover no-repeat #3d6a96;font-family:'Helvetica Neue',Helvetica,Arial,system-ui,sans-serif;">

 <!-- Menu bar -->
 <div id="os-menubar" style="position:absolute;top:0;left:0;right:0;height:22px;z-index:1010;display:flex;align-items:center;justify-content:space-between;padding:0 12px;background:rgba(238,238,238,.82);backdrop-filter:blur(18px) saturate(1.6);-webkit-backdrop-filter:blur(18px) saturate(1.6);border-bottom:1px solid rgba(0,0,0,.18);color:#1b1b1b;font-size:13px;line-height:22px;">
 <div style="display:flex;align-items:center;gap:18px;">
 <span style="font-weight:700;">LazyOS</span>
 <span class="hidden sm:inline">File</span>
 <span class="hidden sm:inline">Edit</span>
 <span class="hidden sm:inline">View</span>
 <span class="hidden sm:inline">Go</span>
 <span class="hidden sm:inline">Window</span>
 <span class="hidden sm:inline">Help</span>
 </div>
 <div style="display:flex;align-items:center;gap:14px;">
 <i class="fa-solid fa-wifi" style="font-size:12px;"></i>
 <i class="fa-solid fa-battery-full" style="font-size:12px;"></i>
 <span id="os-clock">Mon 9:41 AM</span>
 <i class="fa-solid fa-magnifying-glass" style="font-size:12px;"></i>
 </div>
 </div>

 <!-- Desktop drive icon -->
 <div style="position:absolute;top:38px;right:18px;width:84px;text-align:center;color:#fff;font-size:12px;text-shadow:0 1px 3px rgba(0,0,0,.8);user-select:none;">
 <div style="width:54px;height:44px;margin:0 auto 4px;border-radius:7px;background:linear-gradient(#e9e9ec,#b5b5bb);border:1px solid #8d8d93;box-shadow:0 2px 5px rgba(0,0,0,.45);position:relative;">
 <div style="position:absolute;left:8px;right:8px;bottom:8px;height:4px;border-radius:2px;background:#7d7d83;"></div>
 <div style="position:absolute;right:11px;bottom:15px;width:5px;height:5px;border-radius:50%;background:#46c26a;"></div>
 </div>
 LazyList HD
 </div>

 <!-- Dock -->
 <div id="os-dock" style="position:absolute;bottom:8px;left:50%;transform:translateX(-50%);z-index:1010;display:flex;align-items:flex-end;gap:10px;padding:7px 12px 8px;border-radius:16px;background:rgba(255,255,255,.27);backdrop-filter:blur(14px) saturate(1.5);-webkit-backdrop-filter:blur(14px) saturate(1.5);border:1px solid rgba(255,255,255,.55);box-shadow:0 8px 24px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.5);">
 <button onclick="document.getElementById('desync_modal').showModal()" class="os-dock-btn" style="--c1:#5ec8ff;--c2:#1f6fe0;" aria-label="Browser"><i class="fa-solid fa-compass"></i><span class="os-tip">Browser</span></button>
 <button onclick="document.getElementById('chat_modal').showModal()" class="os-dock-btn" style="--c1:#7be07f;--c2:#1ca64a;" aria-label="Messages"><i class="fa-solid fa-comments"></i><span class="os-tip">Messages</span></button>
 <button onclick="document.getElementById('movies_modal').showModal()" class="os-dock-btn" style="--c1:#ff8a7a;--c2:#d9302a;" aria-label="Movies"><i class="fa-solid fa-film"></i><span class="os-tip">Movies</span></button>
 <button onclick="window.open('http://6aebd3ffb07dd.site123.me','_blank')" class="os-dock-btn" style="--c1:#c79bff;--c2:#7a3fe0;" aria-label="AI Chat"><i class="fa-solid fa-robot"></i><span class="os-tip">AI CHAT</span></button>
 <button onclick="document.getElementById('notes_modal').showModal()" class="os-dock-btn" style="--c1:#ffe97a;--c2:#f2b705;" aria-label="Notes"><i class="fa-solid fa-note-sticky"></i><span class="os-tip">Notes</span></button>
 <button onclick="document.getElementById('calc_modal').showModal()" class="os-dock-btn" style="--c1:#8d8d94;--c2:#2f2f33;" aria-label="Calculator"><i class="fa-solid fa-calculator"></i><span class="os-tip">Calculator</span></button>
 <button onclick="document.getElementById('todo_modal').showModal()" class="os-dock-btn" style="--c1:#ffffff;--c2:#d8d8dc;" aria-label="Reminders"><i class="fa-solid fa-list-check" style="color:#ff453a;filter:none;"></i><span class="os-tip">Reminders</span></button>
 <button onclick="document.getElementById('settings_modal').showModal()" class="os-dock-btn" style="--c1:#b9b9c1;--c2:#5d5d66;" aria-label="Settings"><i class="fa-solid fa-gear"></i><span class="os-tip">Settings</span></button>
 <div style="width:1px;height:42px;background:rgba(255,255,255,.55);align-self:center;margin:0 2px;"></div>
 <button onclick="exitOSMode()" class="os-dock-btn" style="--c1:#9a9aa3;--c2:#3c3c44;" aria-label="Log Out"><i class="fa-solid fa-power-off" style="color:#ff6b6b;"></i><span class="os-tip">Log Out</span></button>
 </div>
</div>

