<header class="sticky top-0 z-[90] border-b-2 border-[var(--border-color)] bg-[var(--surface-color)]/90 backdrop-blur-md shadow-sm transition-all duration-300">
 <div id="announcement-banner" class="relative bg-gradient-to-r from-[var(--primary-color)] to-[var(--secondary-color)] px-4 py-2.5 text-center text-sm font-bold text-white shadow-sm flex flex-wrap items-center justify-center gap-2" data-ai-namespace="global_messages" data-ai-record-id="2291662">
 <i class="fa-solid fa-bullhorn text-white/90"></i>
