 <button type="button" onclick="document.getElementById('announcement-banner').style.display='none'" class="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-white/80 hover:text-white transition-colors flex items-center justify-center rounded-full hover:bg-white/20" aria-label="Dismiss announcement">
 <i class="fa-solid fa-xmark text-lg"></i>
