function $(id){return document.getElementById(id);}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function closeDlg(id){var d=$(id);if(d&&d.open)d.close();}

/* toast */
var toastT;
function toast(title,msg){var t=$('submit-toast');if(!t)return;var h=t.querySelector('h3'),d=t.querySelector('.text-sm');if(h)h.textContent=title;if(d)d.textContent=msg;t.classList.remove('hidden');clearTimeout(toastT);toastT=setTimeout(function(){t.classList.add('hidden');},3200);}

/* dialogs: X buttons + backdrop always close */
document.addEventListener('click',function(e){
 var t=e.target;if(!t||!t.closest)return;
 var dlg=t.closest('dialog');
 var b=t.closest('form[method="dialog"] button');
 if(b&&dlg){e.preventDefault();dlg.close();return;}
 if(t.tagName==='DIALOG'&&t.open){t.close();}
});

/* launching */
var currentKey=null;
function altsFor(key){
 var base=(window.altLinksCache&&window.altLinksCache[key])||[];
 var user=(LS.get('ll_user_alts',{})[key])||[];
 return base.concat(user).filter(function(l){return l&&l.url&&l.approved!==false;});
}
function normU(u){return String(u||'').replace(/&+$/,'').replace(/\/+$/,'').replace(/^http:/i,'https:').toLowerCase();}
function distinctAlts(key,mainUrl){
 var seen={};seen[normU(mainUrl)]=1;
 return altsFor(key).filter(function(l){var n=normU(l.url);if(!n||seen[n])return false;seen[n]=1;return true;});
}
function launchURL(url,title){
 if(!url)return;
 var mode=($('launchMode')||{}).value||'normal';
 title=title||'LazyList';
 if(mode==='aboutBlank'){
 var w=window.open('about:blank','_blank');
 if(!w){window.open(url,'_blank');return;}
 try{
 w.document.title=title;
 w.document.body.style.cssText='margin:0;background:#000;';
 var f=w.document.createElement('iframe');
 f.src=url;f.style.cssText='border:0;width:100%;height:100vh;';
 f.setAttribute('allowfullscreen','');
 w.document.body.appendChild(f);
 }catch(err){w.location.href=url;}
 }else if(mode==='blob'){
 var html='<!doctype html><html><head><meta charset="utf-8"><title>'+esc(title)+'</title></head><body style="margin:0;background:#000"><iframe src="'+esc(url)+'" style="border:0;width:100%;height:100vh" allowfullscreen></iframe></body></html>';
 var u=URL.createObjectURL(new Blob([html],{type:'text/html'}));
 if(!window.open(u,'_blank'))window.open(url,'_blank');
 }else{
 window.open(url,'_blank');
 }
}
function mkLink(label,url,title){
 var a=document.createElement('a');
 a.href='#';a.setAttribute('data-url',url);a.setAttribute('data-title',title);
 a.className='btn min-h-12 btn-outline justify-start rounded-full border-2 border-[var(--border-color)] bg-[var(--background-color)] text-[var(--text-color)] hover:bg-[var(--primary-color)] hover:border-[var(--primary-color)] hover:text-white font-bold';
 a.onclick=function(ev){return window.launchGame(ev,a);};
 a.innerHTML='<i class="fa-solid fa-arrow-up-right-from-square"></i> ';
 a.appendChild(document.createTextNode(label));
 return a;
}
window.showLaunchOptions=function(e,el){
 if(e&&e.preventDefault)e.preventDefault();
 var url=(el.getAttribute('data-url')||el.getAttribute('href')||'').replace(/&+$/,'');
 var title=el.getAttribute('data-title')||'Launch';
 currentKey=el.getAttribute('data-key');
 var alts=distinctAlts(currentKey,url);
 var list=$('launch_modal_list');
 if(!list||!alts.length){launchURL(url,title);return false;}
 list.innerHTML='';
 list.appendChild(mkLink(title+' - Main Link',url,title));
 alts.forEach(function(l,i){list.appendChild(mkLink(l.label||('Link '+(i+2)),l.url,title));});
 $('launch_modal_title').textContent=title;
 $('game_launch_modal').showModal();
 return false;
};
window.launchGame=function(e,el){
 if(e&&e.preventDefault)e.preventDefault();
 closeDlg('game_launch_modal');closeDlg('more_links_modal');
 launchURL(el.getAttribute('data-url'),el.getAttribute('data-title'));
 return false;
};
window.reportBrokenLink=function(){
