 toast('Thanks!','Tell us which link is broken in our Discord.');
 window.open(DISCORD,'_blank');
};

/* mode choice + OS mode */

var OS_WINDOWS={desync_modal:'Browser',chat_modal:'Messages',movies_modal:'Movies',notes_modal:'Notes',calc_modal:'Calculator',todo_modal:'Reminders'};
function addTitleBars(){
 Object.keys(OS_WINDOWS).forEach(function(id){
 var d=$(id);if(!d)return;var box=d.querySelector('.modal-box');if(!box||box.querySelector('.os-titlebar'))return;
 var bar=document.createElement('div');bar.className='os-titlebar';
 bar.innerHTML='<button type="button" class="os-dot" style="background:#fc605c" aria-label="Close"></button><button type="button" class="os-dot" style="background:#fdbc40" aria-label="Minimize"></button><button type="button" class="os-dot" style="background:#34c84a" aria-label="Zoom"></button><span class="os-title">'+OS_WINDOWS[id]+'</span>';
 var dots=bar.querySelectorAll('.os-dot');
 dots[0].onclick=dots[1].onclick=function(){d.close();};
 dots[2].onclick=function(){var full=box.style.width==='100vw';box.style.width=full?'':'100vw';box.style.height=full?'':'calc(100vh - 22px)';box.style.maxWidth=full?'':'none';};
 box.insertBefore(bar,box.firstChild);
 });
}
function removeTitleBars(){Array.prototype.forEach.call(document.querySelectorAll('.os-titlebar'),function(b){b.remove();});}

function chime(){
 try{
 var AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
 var c=new AC();if(c.state==='suspended'){try{c.close();}catch(e){}if(!window.__chimeWait){window.__chimeWait=true;var again=function(){document.removeEventListener('pointerdown',again,true);document.removeEventListener('keydown',again,true);window.__chimeWait=false;chime();};document.addEventListener('pointerdown',again,true);document.addEventListener('keydown',again,true);}return;}var t=c.currentTime,master=c.createGain();
 master.gain.value=0.22;master.connect(c.destination);
 [[185.0,0],[277.18,0],[369.99,0.01],[466.16,0.02],[554.37,0.04],[739.99,0.06]].forEach(function(n){
 var o=c.createOscillator(),g=c.createGain();
 o.type='sine';o.frequency.value=n[0];
 g.gain.setValueAtTime(0.0001,t+n[1]);
 g.gain.linearRampToValueAtTime(0.5,t+n[1]+0.06);
 g.gain.exponentialRampToValueAtTime(0.0001,t+3.4);
 o.connect(g);g.connect(master);o.start(t+n[1]);o.stop(t+3.5);
 });
 setTimeout(function(){try{c.close();}catch(e){}},4000);
 }catch(e){}
}
var clockT;
function tickClock(){var c=$('os-clock');if(!c)return;var d=new Date();c.textContent=d.toLocaleDateString([], {weekday:'short'})+' '+d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'});}
function showChoice(){var o=$('choice-overlay');if(!o)return;o.classList.remove('hidden');o.style.display='flex';requestAnimationFrame(function(){o.style.opacity='1';});}
function hideChoice(){var o=$('choice-overlay');if(!o)return;o.style.opacity='0';setTimeout(function(){o.style.display='none';},300);}
function enterOS(){
 var os=$('os-desktop');if(!os||os.style.display==='block')return;
 document.documentElement.classList.add('os-only');
 os.classList.remove('hidden');os.style.display='block';document.body.style.overflow='hidden';document.body.classList.add('os-mode');addTitleBars();
 tickClock();clearInterval(clockT);clockT=setInterval(tickClock,20000);
 chime();
}
function hideOS(){
 var os=$('os-desktop');if(!os)return;
 Object.keys(OS_WINDOWS).concat(['settings_modal']).forEach(closeDlg);
 os.style.display='none';document.body.style.overflow='';document.body.classList.remove('os-mode');document.documentElement.classList.remove('os-only');removeTitleBars();clearInterval(clockT);
}
window.exitOSMode=function(){
 hideOS();
 if(location.hash==='#os')history.replaceState(null,'',location.href.split('#')[0]+'#home');
 if(window.opener){try{window.close();}catch(e){}}
};
function openOSTab(){location.hash='os';}
window.chooseMode=function(m){if(m==='os')openOSTab();};
window.addEventListener('hashchange',function(){if(location.hash==='#os')enterOS();else hideOS();});
window.skipChoiceNextTime=function(){LS.set('ll_skip_choice',true);hideChoice();};

/* tab disguise */
function setFavicon(href){var l=document.querySelector('link[rel*="icon"]');if(!l){l=document.createElement('link');l.rel='icon';document.head.appendChild(l);}l.href=href;}
Array.prototype.forEach.call(document.querySelectorAll('.disguise-btn'),function(b){
 b.addEventListener('click',function(){
 var t=b.getAttribute('data-title'),i=b.getAttribute('data-icon');
 if(i==='reset'){document.title='LazyList';setFavicon(LOGO);LS.set('ll_disguise',null);}
 else{document.title=t;setFavicon(i);LS.set('ll_disguise',{t:t,i:i});}
 if(document.activeElement&&document.activeElement.blur)document.activeElement.blur();
 });
});
var dg=LS.get('ll_disguise',null);if(dg&&dg.t){document.title=dg.t;setFavicon(dg.i);}

/* settings */
var ab=$('setting_auto_blank'),pk=$('setting_panic_key'),pu=$('setting_panic_url');
if(ab){ab.checked=LS.get('ll_auto_blank',false);ab.addEventListener('change',function(){LS.set('ll_auto_blank',ab.checked);});}
if(pk){pk.checked=LS.get('ll_panic_key',false);pk.addEventListener('change',function(){LS.set('ll_panic_key',pk.checked);});}
if(pu){pu.value=LS.get('ll_panic_url',pu.value);pu.addEventListener('input',function(){LS.set('ll_panic_url',pu.value);});}
function panicUrl(){var u=((pu&&pu.value)||'').trim();if(u&&!/^[a-z]+:\/\//i.test(u))u='https://'+u;return u||'https://classroom.google.com';}
document.addEventListener('keydown',function(e){
 if(e.key!=='`'||!pk||!pk.checked)return;
 var tag=((e.target&&e.target.tagName)||'').toLowerCase();
 if(tag==='input'||tag==='textarea'||tag==='select')return;
 e.preventDefault();window.location.replace(panicUrl());
});
function cloak(redirect){
 var w=window.open('about:blank','_blank');
 if(!w){toast('Popup blocked','Allow popups for this site and try again.');return false;}
 try{
 w.document.title=document.title;
 w.document.body.style.cssText='margin:0;background:#000;';
 var f=w.document.createElement('iframe');
 f.src=location.href;f.style.cssText='border:0;width:100%;height:100vh;';
 f.setAttribute('allowfullscreen','');
 w.document.body.appendChild(f);
 }catch(err){}
 if(redirect)window.location.replace(panicUrl());
 return true;
}
var autoDone=false;
document.addEventListener('click',function(e){
 if(autoDone||!ab||!ab.checked||window.self!==window.top)return;
 if(e.target.closest&&e.target.closest('#settings_modal'))return;
 autoDone=true;cloak(true);
},true);
