 ex.addEventListener('click',function(){
 var html='<!DOCTYPE html>\n'+document.documentElement.outerHTML;
 var a=document.createElement('a');
 a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));
 a.download='lazylist.html';document.body.appendChild(a);a.click();
 setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},500);
 });
}

/* library: search / favorites / likes / sort / multi-link */
var grid=$('proxyGrid');
var favs=LS.get('ll_favs',{}),likes=LS.get('ll_likes',{}),dislikes=LS.get('ll_dislikes',{});
var state={q:'',fav:false,multi:false,sort:false};
function cards(){return grid?Array.prototype.slice.call(grid.querySelectorAll('.proxy-card')):[];}
function keyOf(c){return c.getAttribute('data-key')||c.getAttribute('data-title');}
function paint(c){
 var k=keyOf(c);
 var lb=c.querySelector('.btn-like'),db=c.querySelector('.btn-dislike'),fb=c.querySelector('.btn-fav');
 function set(btn,on,onCls,offCls,color){if(!btn)return;var i=btn.querySelector('i');if(i)i.className=(on?'fa-solid ':'fa-regular ')+offCls+' text-sm pointer-events-none';btn.style.color=on?color:'';btn.style.borderColor=on?color:'';}
 set(lb,!!likes[k],'','fa-heart','#ef4444');
 set(db,!!dislikes[k],'','fa-thumbs-down','#3b82f6');
 set(fb,!!favs[k],'','fa-star','#eab308');
 var lc=c.querySelector('.like-count'),dc=c.querySelector('.dislike-count');
 if(lc)lc.textContent=(parseInt(c.getAttribute('data-ll-likes'),10)||0)+(likes[k]?1:0);
 if(dc)dc.textContent=(parseInt(c.getAttribute('data-ll-dislikes'),10)||0)+(dislikes[k]?1:0);
}
function apply(){
 var n=0;
 cards().forEach(function(c,i){
 var t=(c.getAttribute('data-title')||'').toLowerCase(),k=keyOf(c);
 var ok=t.indexOf(state.q)>-1&&(!state.fav||favs[k])&&(!state.multi||distinctAlts(k,c.getAttribute('data-url')||c.getAttribute('href')).length>0);
 c.style.display=ok?'':'none';if(ok)n++;
 var base=parseFloat(c.getAttribute('data-ll-base'));
 var lk=(parseInt(c.getAttribute('data-ll-likes'),10)||0)+(likes[k]?1:0);
 c.style.order=state.sort?String(-lk*1000+base):String(base);
 });
 var pc=$('proxyCount');if(pc)pc.textContent=n;
}
function toggleBtn(id,on,color){var b=$(id);if(!b)return;b.style.color=on?color:'';b.style.borderColor=on?color:'';}
cards().forEach(function(c,i){
 var o=parseFloat(c.style.order);c.setAttribute('data-ll-base',isNaN(o)?i:o);
 var lc=c.querySelector('.like-count'),dc=c.querySelector('.dislike-count');
 c.setAttribute('data-ll-likes',(lc&&parseInt(lc.textContent,10))||0);
 c.setAttribute('data-ll-dislikes',(dc&&parseInt(dc.textContent,10))||0);
 paint(c);
});
var si=$('proxySearch');if(si)si.addEventListener('input',function(){state.q=si.value.trim().toLowerCase();apply();});
var fb=$('favFilterBtn');if(fb)fb.addEventListener('click',function(){state.fav=!state.fav;toggleBtn('favFilterBtn',state.fav,'#eab308');apply();});
var sb=$('sortLikesBtn');if(sb)sb.addEventListener('click',function(){state.sort=!state.sort;toggleBtn('sortLikesBtn',state.sort,'#ef4444');apply();});
var mb=$('filterMultiLinksBtn');if(mb)mb.addEventListener('click',function(){state.multi=!state.multi;toggleBtn('filterMultiLinksBtn',state.multi,'#a855f7');apply();});
var lm=$('launchMode');if(lm){lm.value=LS.get('ll_launch_mode',lm.value);lm.addEventListener('change',function(){LS.set('ll_launch_mode',lm.value);});}

/* card buttons (capture so the card link never fires) */
document.addEventListener('click',function(e){
 var b=e.target.closest&&e.target.closest('.btn-like,.btn-dislike,.btn-fav');
 if(!b)return;
 e.preventDefault();e.stopPropagation();
 var c=b.closest('.proxy-card');if(!c)return;
 var k=keyOf(c);
 if(b.classList.contains('btn-like')){if(likes[k])delete likes[k];else{likes[k]=1;delete dislikes[k];}}
 else if(b.classList.contains('btn-dislike')){if(dislikes[k])delete dislikes[k];else{dislikes[k]=1;delete likes[k];}}
 else{if(favs[k])delete favs[k];else favs[k]=1;}
 LS.set('ll_likes',likes);LS.set('ll_dislikes',dislikes);LS.set('ll_favs',favs);
 paint(c);apply();
},true);
/* cards that were plain links -> same launch menu */
document.addEventListener('click',function(e){
 var c=e.target.closest&&e.target.closest('a.proxy-card');
 if(c&&!c.hasAttribute('onclick')){e.preventDefault();window.showLaunchOptions(e,c);}
});

