 if(!url||!currentKey)return;
 var all=LS.get('ll_user_alts',{});(all[currentKey]=all[currentKey]||[]).push({label:label||'My link',url:url,approved:true});
 LS.set('ll_user_alts',all);af.reset();closeDlg('add_alt_link_modal');
 toast('Link saved','Added to this proxy on this device.');apply();
});

