 nt.addEventListener('input',function(){
 if(ns)ns.textContent='Saving...';clearTimeout(nT);
 nT=setTimeout(function(){LS.set('ll_os_notes',nt.value);if(ns)ns.textContent='Saved';},300);
 });
}

/* Calculator */
(function(){
 var disp=$('calc_display');if(!disp)return;
 var cur='0',prev=null,op=null,fresh=false;
 function fmt(n){if(!isFinite(n))return 'Error';var r=parseFloat(n.toPrecision(10));var t=String(r);return t.length>12?r.toExponential(5):t;}
 function compute(a,b,o){return o==='+'?a+b:o==='\u2212'?a-b:o==='\u00d7'?a*b:b===0?NaN:a/b;}
 function key(k){
 if(cur==='Error'&&k!=='AC'){cur='0';}
 if(/^\d$/.test(k)){if(fresh||cur==='0'){cur=k;fresh=false;}else if(cur.length<12)cur+=k;}
 else if(k==='.'){if(fresh){cur='0.';fresh=false;}else if(cur.indexOf('.')<0)cur+='.';}
 else if(k==='AC'){cur='0';prev=null;op=null;fresh=false;}
 else if(k==='neg'){if(parseFloat(cur)!==0)cur=cur.charAt(0)==='-'?cur.slice(1):'-'+cur;}
 else if(k==='%'){cur=fmt(parseFloat(cur)/100);}
 else if(k==='='){if(op!==null){cur=fmt(compute(prev,parseFloat(cur),op));prev=null;op=null;fresh=true;}}
 else{if(op!==null&&!fresh){cur=fmt(compute(prev,parseFloat(cur),op));}prev=parseFloat(cur);if(isNaN(prev)){prev=null;op=null;}else op=k;fresh=true;}
 disp.textContent=cur;
 }
 Array.prototype.forEach.call(document.querySelectorAll('.calc-k'),function(b){b.addEventListener('click',function(){key(b.getAttribute('data-k'));});});
})();

/* Reminders (saved) */
(function(){
 var list=$('todo_list'),form=$('todo_form'),inp=$('todo_input');if(!list||!form)return;
 var items=LS.get('ll_os_todos',[]);if(!Array.isArray(items))items=[];
 function save(){LS.set('ll_os_todos',items);}
 function render(){
 list.innerHTML='';
 if(!items.length){var e=document.createElement('li');e.style.color='#999';e.textContent='No reminders yet.';list.appendChild(e);return;}
 items.forEach(function(it,i){
 var li=document.createElement('li');if(it.d)li.className='done';
 var cb=document.createElement('input');cb.type='checkbox';cb.checked=!!it.d;
 cb.addEventListener('change',function(){it.d=cb.checked;save();render();});
 var sp=document.createElement('span');sp.textContent=it.t;
 var del=document.createElement('button');del.type='button';del.setAttribute('aria-label','Delete');del.textContent='\u2715';
 del.addEventListener('click',function(){items.splice(i,1);save();render();});
 li.appendChild(cb);li.appendChild(sp);li.appendChild(del);list.appendChild(li);
 });
 }
 form.addEventListener('submit',function(e){e.preventDefault();var t=inp.value.trim();if(!t)return;items.push({t:t,d:false});inp.value='';save();render();});
 render();
})();

/* start in OS mode when asked to */
if(location.hash==='#os')enterOS();
else if(LS.get('ll_auto_os',false)&&location.hash!=='#home'){history.replaceState(null,'',location.href.split('#')[0]+'#os');enterOS();}

apply();
})();

</script>
